import {BranchName, Link, Truncate} from '@primer/react'
import {branchPath, tagPath} from '@github-ui/paths'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {testIdProps} from '@github-ui/test-id-props'
import type {DeploymentData} from '../../types/list'

import styles from './GitRef.module.css'

export const GitRef = ({
  owner,
  repo,
  gitRef,
  refExists,
  pullRequestID,
  pullRequestPath,
  prefix,
}: Pick<
  DeploymentData,
  'owner' | 'repo' | 'gitRef' | 'refExists' | 'sha' | 'pullRequestID' | 'pullRequestPath' | 'prefix'
>) => {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  let refLink
  if (gitRef) {
    if (refExists) {
      const linkHref =
        prefix === 'refs/heads/' ? branchPath({owner, repo, branch: gitRef}) : tagPath({owner, repo, tag: gitRef})
      const linkLabel = prefix === 'refs/heads/' ? `${gitRef} branch` : `${gitRef} tag`
      refLink = (
        <BranchName href={linkHref} aria-label={linkLabel} {...testIdProps('deployments-list-branch-name')}>
          <Truncate title={gitRef}>{gitRef}</Truncate>
        </BranchName>
      )
    } else {
      refLink = (
        <BranchName as="code" className={styles.BranchName} {...testIdProps('deployments-list-branch-name')}>
          <Truncate title={gitRef}>{gitRef}</Truncate>
        </BranchName>
      )
    }
  }

  return (
    <span className={styles.refContainer}>
      {refLink}
      <span>
        {pullRequestID && pullRequestPath ? (
          <Link
            href={pullRequestPath}
            {...getHovercardAttributesForType('pull_request', {url: `${pullRequestPath}/hovercard`})}
          >
            <span className={styles.pullRequestId}>(#{pullRequestID})</span>
          </Link>
        ) : null}
      </span>
    </span>
  )
}
