import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLText} from '@github-ui/safe-html/VerifiedHTML'
import {LinkExternalIcon} from '@primer/octicons-react'
import {Heading, RelativeTime} from '@primer/react'
import {STATUSES} from '../utils/statuses'
import {use} from 'react'
import {EnvironmentContext} from '../App'
import styles from './DeploymentCardsSection.module.css'

const maxDisplay = 10

export type DeploymentCardProps = {
  name: SafeHTMLString | undefined
  environment: string | undefined
  createdAt: string | undefined
  logURL: string | undefined
  environmentURL: string | undefined
  state: string | undefined
}

function StatusBadge(state: string | undefined) {
  if (state && state in STATUSES) {
    const {color, icon: Icon} = STATUSES[state as keyof typeof STATUSES]
    return (
      <span style={{color}}>
        <Icon aria-label={`Deployment ${state}`} />
      </span>
    )
  } else {
    return null
  }
}

export function DeploymentCardsSection(data: DeploymentCardProps[]) {
  const selectedEnv = use(EnvironmentContext)
  const environmentAdjective = 'pinned'
  const header = !selectedEnv ? 'All deployments' : `${selectedEnv} deployments`
  return (
    <div>
      <div className={styles.headerSection}>
        <Heading as="h2" className={styles.heading}>
          {header}
        </Heading>
        <span data-testid={`${environmentAdjective}-header`} className={styles.subheading}>
          {selectedEnv ? 'Latest deployments' : `Latest deployments from ${environmentAdjective} environments`}
        </span>
      </div>
      <div className={styles.grid}>
        {data.slice(0, maxDisplay).map((deployment, index) => (
          <div
            data-testid="deployment-card"
            className={styles.card}
            // eslint-disable-next-line @eslint-react/no-array-index-key
            key={index}
          >
            <div className={styles.cardContent}>
              <div>
                {StatusBadge(deployment.state)}
                <span className={styles.envName}>{deployment.environment}</span>
              </div>
              <div>
                <span className={styles.mutedText}>Last</span>
                {deployment.logURL ? (
                  <a href={deployment.logURL} className={styles.deployedLink}>
                    deployed
                  </a>
                ) : (
                  <span className={styles.mutedSmallText}>deployed</span>
                )}
                <RelativeTime datetime={deployment.createdAt} format="relative" className={styles.RelativeTime} />
              </div>
              {deployment.environmentURL ? (
                <div>
                  <a href={deployment.environmentURL} className={styles.envUrl}>
                    {deployment.environmentURL}
                  </a>
                </div>
              ) : (
                <div>
                  <span className={styles.commitName}>
                    <VerifiedHTMLText as="span" html={deployment.name} />
                  </span>
                </div>
              )}
            </div>
            <span className={styles.cardActions}>
              {deployment.environmentURL && (
                <a href={deployment.environmentURL} aria-label={`View deployment to ${deployment.environment}`}>
                  <LinkExternalIcon className={styles.externalIcon} />
                </a>
              )}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}
