import {Link} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import styles from './Trigger.module.css'
import type {DeploymentData} from '../../types/list'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'

export const Trigger = ({
  creatorPath,
  creatorName,
  creatorAvatar,
  workflowRunNumber,
  workflowName,
}: Pick<DeploymentData, 'creatorPath' | 'creatorName' | 'creatorAvatar' | 'workflowRunNumber' | 'workflowName'>) => {
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  return (
    <span className={styles.wrapper}>
      <Link
        href={creatorPath}
        muted
        {...getHovercardAttributesForType('user', {login: creatorName})}
        className={styles.creatorLink}
        target="_blank"
      >
        <GitHubAvatar src={creatorAvatar} size={16} className={styles.avatar} />
        {creatorName}
      </Link>

      {workflowRunNumber && workflowName ? (
        <span className={styles.workflowInfo}>{`via ${workflowName} #${workflowRunNumber}`}</span>
      ) : null}
    </span>
  )
}
